package repository

import (
	"context"
	"encoding/json"
	"time"

	"github.com/Wei-Shaw/sub2api/internal/service"
)

// ListDueUpstreamWalletAccounts hydrates only the next batch, including its proxies.
// checked_at is generated by the worker in UTC. Compare whole ISO seconds so
// timestamps written with or without fractional seconds have the same ordering.
func (r *accountRepository) ListDueUpstreamWalletAccounts(ctx context.Context, now time.Time, limit int) ([]service.Account, error) {
	if limit <= 0 {
		return nil, nil
	}
	rows, err := r.sql.QueryContext(ctx, `
		WITH candidates AS (
			SELECT id, left(extra #>> '{upstream_wallet,checked_at}', 19) AS checked
			FROM accounts WHERE deleted_at IS NULL
		) SELECT id FROM candidates
		WHERE checked IS NULL OR checked <= $1 OR checked > $2
		ORDER BY checked NULLS FIRST, id LIMIT $3
	`, now.UTC().Add(-time.Hour).Format("2006-01-02T15:04:05"), now.UTC().Format("2006-01-02T15:04:05"), limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	ids := make([]int64, 0, limit)
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	accounts, err := r.GetByIDs(ctx, ids)
	if err != nil {
		return nil, err
	}
	result := make([]service.Account, 0, len(accounts))
	for _, account := range accounts {
		result = append(result, *account)
	}
	return result, nil
}

// SaveUpstreamWallet is metadata-only. Compare the observed credentials and last
// snapshot so an edit or a concurrent poll cannot attach stale funds to an account.
func (r *accountRepository) SaveUpstreamWallet(ctx context.Context, account *service.Account, snapshot *service.UpstreamWalletSnapshot) error {
	if account == nil || snapshot == nil {
		return service.ErrAccountNilInput
	}
	credentials, err := json.Marshal(normalizeJSONMap(account.Credentials))
	if err != nil {
		return err
	}
	old, err := json.Marshal(account.Extra["upstream_wallet"])
	if err != nil {
		return err
	}
	payload, err := json.Marshal(snapshot)
	if err != nil {
		return err
	}
	res, err := r.sql.ExecContext(ctx, `
		UPDATE accounts SET extra=jsonb_set(COALESCE(extra,'{}'::jsonb),'{upstream_wallet}',$1::jsonb,true),updated_at=now()
		WHERE id=$2 AND deleted_at IS NULL AND platform=$3 AND type=$4 AND credentials=$5::jsonb
		  AND proxy_id IS NOT DISTINCT FROM $6 AND COALESCE(extra->'upstream_wallet','null'::jsonb)=$7::jsonb
	`, string(payload), account.ID, account.Platform, account.Type, string(credentials), account.ProxyID, string(old))
	if err != nil {
		return err
	}
	affected, err := res.RowsAffected()
	if err == nil && affected == 0 {
		return service.ErrUpstreamBillingProbeIdentityChanged
	}
	return err
}
